			sidebarCharacter.src = ART.sidebar;
			sidebarCharacter.dataset.skinChrome = "sidebar-character";
			sidebarCharacter.dataset.skinOwner = SKIN_OWNER;
			sidebarCharacter.setAttribute("aria-hidden", "true");

			const wordmark = doc.createElement("span");
			wordmark.className = "skin-wordmark";
			wordmark.dataset.skinChrome = "titlebar-wordmark";
			wordmark.dataset.skinOwner = SKIN_OWNER;
